package com.trampolim.api.education;

import static org.junit.jupiter.api.Assertions.*;
import java.net.*;import java.net.http.*;import java.util.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import com.trampolim.api.BackendApplication;

class AssessmentHttpPostgresTest {
    private final HttpClient client=HttpClient.newHttpClient();private final ObjectMapper json=new ObjectMapper();private String base;
    @Test void realApiGradesWithoutLeakingAnswersAndVerifiesConsentedAward()throws Exception{
        String schema="assessment_http_"+UUID.randomUUID().toString().replace("-","");String url=env("CAPACITA_DB_URL","jdbc:postgresql://localhost:5434/trampolim_capacita_db");var admin=new JdbcTemplate(new DriverManagerDataSource(url,env("CAPACITA_DB_USERNAME","trampolim_capacita"),env("CAPACITA_DB_PASSWORD","dev_capacita_only")));admin.execute("CREATE SCHEMA "+schema);
        try(var context=new SpringApplicationBuilder(BackendApplication.class).run("--server.port=0","--spring.jpa.hibernate.ddl-auto=validate","--app.mail.enabled=false","--capacita.admin-emails=assessment-teacher@example.test","--trampolim.datasource.capacita.url="+url+(url.contains("?")?"&":"?")+"currentSchema="+schema)){
            base="http://127.0.0.1:"+context.getEnvironment().getRequiredProperty("local.server.port")+"/api/capacita";
            String teacher=register("assessment-teacher@example.test"),student=register("assessment-student@example.test"),other=register("assessment-other@example.test");long course=id(send("POST","/learning/courses","{\"title\":\"Assessment course\",\"category\":\"Math\",\"status\":\"PUBLISHED\"}",teacher));long subject=id(send("POST","/learning/courses/"+course+"/subjects","{\"title\":\"Subject\",\"sortOrder\":0}",teacher));long module=id(send("POST","/learning/subjects/"+subject+"/modules","{\"title\":\"Module\",\"sortOrder\":0}",teacher));
            String question=UUID.randomUUID().toString(),correct=UUID.randomUUID().toString(),wrong=UUID.randomUUID().toString();var definition=Map.of("title","Mini proof","passPercent",75,"maxAttempts",1,"requireStudy",false,"feedbackEnabled",true,"requiredForCompletion",true,"questions",List.of(Map.of("id",question,"kind","MCQ","text","Select A","points",4,"options",List.of(Map.of("id",correct,"text","A"),Map.of("id",wrong,"text","B")),"correctOptionId",correct,"explanation","Teacher feedback")),"competencies",List.of(Map.of("id",UUID.randomUUID().toString(),"name","Logical reasoning","description","Assessment proof")));
            String payload=json.writeValueAsString(Map.of("courseId",course,"subjectId",subject,"moduleId",module,"status","PUBLISHED","definition",definition));assertEquals(403,send("POST","/learning/assessments",payload,student).statusCode());long assessment=id(send("POST","/learning/assessments",payload,teacher));
            var visible=send("GET","/learning/assessments/"+assessment,null,student);assertEquals(200,visible.statusCode());assertFalse(visible.body().contains("correctOptionId"));assertFalse(visible.body().contains("Teacher feedback"));assertEquals(403,send("GET","/learning/assessments/"+assessment+"?manage=true",null,other).statusCode());
            var started=send("POST","/learning/assessments/"+assessment+"/attempts",null,student);assertEquals(200,started.statusCode(),started.body());String attempt=json.readTree(started.body()).path("id").asText();assertEquals(403,send("GET","/learning/assessment-attempts/"+attempt,null,other).statusCode());String key=UUID.randomUUID().toString();String submit=json.writeValueAsString(Map.of("clientKey",key,"answers",Map.of(question,correct),"score_percent",0,"passed",false));var graded=send("POST","/learning/assessment-attempts/"+attempt+"/submit",submit,student);assertEquals(200,graded.statusCode(),graded.body());assertTrue(json.readTree(graded.body()).path("passed").asBoolean());assertEquals(100,json.readTree(graded.body()).path("score_percent").asInt());assertFalse(graded.body().contains("correctOptionId"));assertEquals(200,send("POST","/learning/assessment-attempts/"+attempt+"/submit",submit,student).statusCode());assertEquals(409,send("POST","/learning/assessments/"+assessment+"/attempts",null,student).statusCode());assertEquals(403,send("GET","/learning/assessments/"+assessment+"/results",null,other).statusCode());
            var awards=json.readTree(send("GET","/learning/competencies",null,student).body());assertEquals(1,awards.size());String award=awards.get(0).path("id").asText();assertEquals(404,send("PUT","/learning/competencies/"+UUID.randomUUID()+"/presentation","{\"highlighted\":true,\"sortOrder\":0}",student).statusCode());assertEquals(204,send("PUT","/learning/competencies/"+award+"/presentation","{\"highlighted\":true,\"sortOrder\":0}",student).statusCode());assertEquals(400,send("POST","/learning/competencies/export","{\"consent\":false}",student).statusCode());assertEquals(200,send("POST","/learning/competencies/export","{\"consent\":true}",student).statusCode());
            String token=json.readTree(send("POST","/learning/competencies/"+award+"/share","{\"consent\":true}",student).body()).path("token").asText();var shared=send("GET","/learning/competencies/shared/"+token,null,null);assertEquals(200,shared.statusCode());assertFalse(shared.body().contains("assessment-student"));assertFalse(shared.body().contains("student_id"));assertFalse(shared.body().contains("share_hash"));assertEquals(204,send("DELETE","/learning/competencies/"+award+"/share",null,student).statusCode());assertEquals(404,send("GET","/learning/competencies/shared/"+token,null,null).statusCode());
            String corporate=context.getBean(com.trampolim.api.security.TrailTokenService.class).issue(com.trampolim.api.security.TrailTokenService.Trail.EMPRESAS,"assessment-student@example.test",1L,0);assertEquals(403,send("GET","/learning/performance",null,corporate).statusCode());var exported=send("GET","/account/export",null,student);assertTrue(json.readTree(exported.body()).has("assessmentAttempts"));assertFalse(exported.body().contains("correctOptionId"));
        }finally{admin.execute("DROP SCHEMA "+schema+" CASCADE");}
    }
    private String register(String email)throws Exception{var response=send("POST","/auth/register","{\"name\":\"Private assessment fixture\",\"email\":\""+email+"\",\"password\":\"AssessmentFixturePassword!\",\"educationStage\":\"HIGH_SCHOOL\",\"ageBand\":\"AGE_18_PLUS\",\"termsAccepted\":true}",null);assertEquals(200,response.statusCode());return json.readTree(response.body()).path("token").asText();}
    private HttpResponse<String> send(String method,String path,String body,String token)throws Exception{var request=HttpRequest.newBuilder(URI.create(base+path)).timeout(java.time.Duration.ofSeconds(30)).header("Content-Type","application/json");if(token!=null)request.header("Authorization","Bearer "+token);return client.send(request.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
    private long id(HttpResponse<String> response)throws Exception{assertEquals(200,response.statusCode(),response.body());return json.readTree(response.body()).path("id").asLong();}
    private static String env(String name,String fallback){String value=System.getenv(name);return value==null||value.isBlank()?fallback:value;}
}
